class Solution {
public:
    int mincostTickets(vector<int>& days, vector<int>& costs) {
        set<int> travel(days.begin(), days.end());
        int last = days.back();
        vector<int> dp(last + 1, 0);
        for (int d = 1; d <= last; d++) {
            if (!travel.count(d)) {
                dp[d] = dp[d - 1];
                continue;
            }
            dp[d] = min({dp[d - 1] + costs[0], dp[max(0, d - 7)] + costs[1], dp[max(0, d - 30)] + costs[2]});
        }
        return dp[last];
    }
};
